104	    /** The sheet's settings as they stood at the end of a day. A setting that is not dated whose
105	     *  value was never kept stands as it is now; one kept only after the day was not set then. */
106	    public AsOfView asOf(String sheetId, LocalDate day) {
107	        Map<String, String> then = history.settings(sheetId, day);
108	        List<String> kept = history.settingsKept(sheetId);
109	        Map<String, String> byUser = new TreeMap<>();
110	        roles(sheetId).forEach(r -> byUser.put(r.getUser(), r.getRole().label()));
111	        Map<String, String> byAction = permissions(sheetId);
112	        for (String key : kept) {
113	            String value = then.get(key);
114	            if (key.startsWith(ROLE)) {
115	                String user = key.substring(ROLE.length());
116	                if (value == null) {
117	                    byUser.remove(user);
118	                } else {
119	                    byUser.put(user, value);
120	                }
121	            } else if (key.startsWith(PERMISSION)) {
122	                byAction.put(key.substring(PERMISSION.length()), value != null ? value : "");
123	            }
124	        }
125	        String numbering = kept.contains(NUMBERING_FROM) ? then.get(NUMBERING_FROM)
126	                : Objects.toString(periodNumberingFrom(sheetId), null);
127	        String entry = kept.contains(ENTRY_DATE) ? then.get(ENTRY_DATE) : Objects.toString(entryDate(sheetId), null);
128	        String grace = kept.contains(GRACE_DAYS) ? then.get(GRACE_DAYS) : Objects.toString(graceDays(sheetId), null);
129	        String escalate = kept.contains(ESCALATE_AFTER) ? then.get(ESCALATE_AFTER)
130	                : Objects.toString(escalateAfter(sheetId), null);
131	        String kinds = kept.contains(PROOF_KINDS) ? then.get(PROOF_KINDS) : sheets.load(sheetId).getProofKinds();
132	        String defaultGrade = kept.contains(DEFAULT_GRADE) ? then.get(DEFAULT_GRADE)
133	                : sheets.load(sheetId).getDefaultGrade();
134	        String sla = kept.contains(REVIEW_SLA) ? then.get(REVIEW_SLA) : Objects.toString(reviewSla(sheetId), null);
135	        String pendingSla = kept.contains(PENDING_SLA) ? then.get(PENDING_SLA)
136	                : Objects.toString(pendingSla(sheetId), null);
137	        String maxOpen = kept.contains(MAX_OPEN) ? then.get(MAX_OPEN) : Objects.toString(maxOpen(sheetId), null);
138	        String scoreMid = kept.contains(SCORE_MID) ? then.get(SCORE_MID) : Objects.toString(scoreMid(sheetId), null);
139	        String scoreHigh = kept.contains(SCORE_HIGH) ? then.get(SCORE_HIGH) : Objects.toString(scoreHigh(sheetId), null);
140	        boolean scoreLog = kept.contains(SCORE_LOG) ? then.get(SCORE_LOG) != null : scoreLog(sheetId);
141	        BigDecimal potNow = pot(sheetId);
142	        String pot = kept.contains(POT) ? then.get(POT) : potNow != null ? potNow.toPlainString() : null;
143	        BigDecimal alertNow = alertThreshold(sheetId);
144	        String alert = kept.contains(ALERT_THRESHOLD) ? then.get(ALERT_THRESHOLD)
145	                : alertNow != null ? alertNow.toPlainString() : null;
146	        String parent = parent(sheetId);
147	        String fiscal = kept.contains(FISCAL_START_MONTH) ? then.get(FISCAL_START_MONTH)
148	                : String.valueOf(fiscalStartMonth(sheetId));
149	        Map<String, List<SettingValue>> dated = history.dated(sheetId, day);
150	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
151	        dated.forEach((key, recorded) -> {
152	            if (key.startsWith(GRADE_TERMS)) {
153	                recorded.stream().filter(v -> !v.getFrom().isAfter(day)).reduce((a, b) -> b)
154	                        .ifPresent(v -> gradeTerms.put(key.substring(GRADE_TERMS.length()), v.getValue().intValue()));
155	            }
156	        });
157	        return new AsOfView(byUser, byAction, numbering != null ? LocalDate.parse(numbering) : null,
158	                grace != null ? Integer.valueOf(grace) : null,
159	                delegations(sheetId).stream().filter(d -> d.madeAsOf(day)).toList(),
160	                inForce(sheetId, "clerk-limit", day, day).map(SettingValue::getValue).orElse(null),
161	                floor(sheetId, day, day),
162	                inForce(sheetId, "cap", day, day).map(SettingValue::getValue).orElse(null),
163	                inForce(sheetId, "terms", day, day).map(v -> v.getValue().intValue()).orElse(START_TERMS),
164	                latePct(sheetId, day, day), history.policyDate(sheetId, day), gradeTerms, dated,
165	                entry != null ? LocalDate.parse(entry) : null, pot != null ? new BigDecimal(pot) : null, parent,
166	                fiscal != null ? Integer.parseInt(fiscal) : 1, alert != null ? new BigDecimal(alert) : null,
167	                escalate != null ? Integer.valueOf(escalate) : null, sla != null ? Integer.valueOf(sla) : null,
168	                kindsOf(kinds), defaultGrade, scoreMid != null ? Integer.valueOf(scoreMid) : null,
169	                scoreHigh != null ? Integer.valueOf(scoreHigh) : null, scoreLog,
170	                maxOpen != null ? Integer.valueOf(maxOpen) : null,
171	                pendingSla != null ? Integer.valueOf(pendingSla) : null);
172	    }
