190	    /** The steward who delegated the steward role to the user by a delegation in force on the sheet's
191	     *  today (the latest made); empty when none is. */
192	    public Optional<String> delegatedBy(String sheetId, String user) {
193	        List<Delegation> made = delegations.findBySheetIdAndUserOrderByIdDesc(sheetId, user);
194	        if (made.isEmpty()) {
195	            return Optional.empty();
196	        }
197	        LocalDate today = sheets.today(sheetId);
198	        return made.stream().filter(d -> d.covers(today)).map(Delegation::getBy).findFirst();
199	    }
