206	    /** Delegate the steward role to a user from a from-date (null for the sheet's today) to a to-date
207	     *  (null for the from-date), inclusive; anyone but a steward by their own role, or a to-date before
208	     *  the from-date, is refused. */
209	    @Transactional
210	    public Delegation delegate(String sheetId, String by, String user, LocalDate from, LocalDate to) {
211	        sheets.lock(sheetId);
212	        if (ownRole(sheetId, by) != Role.STEWARD) {
213	            throw new DelegationRefusedException("Only a steward can delegate the steward role");
214	        }
215	        LocalDate start = from != null ? from : sheets.today(sheetId);
216	        LocalDate end = to != null ? to : start;
217	        if (end.isBefore(start)) {
218	            throw new DelegationRefusedException("The to-date is before the from-date");
219	        }
220	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, user, start, end, by, sheets.today(sheetId)));
221	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + by + " user=" + user + " from=" + start
222	                + " to=" + end);
223	        return saved;
224	    }
