242	    /** Whether the user's role may take the action on the sheet: by the roles the matrix lists for it,
243	     *  else by the standing rule. */
244	    public boolean allows(String sheetId, String user, Permission action) {
245	        Role role = roleOf(sheetId, user);
246	        if (role == Role.VIEWER) {
247	            return false;
248	        }
249	        return permissions.findBySheetIdAndAction(sheetId, action.label())
250	                .map(p -> Arrays.stream(p.getRoles().split(",")).anyMatch(r -> r.equals(role.label())))
251	                .orElseGet(() -> action.standing().contains(role));
252	    }
