254	    /** Refuse the action unless the user's role may take it on the sheet. */
255	    public void refuseUnless(String sheetId, String user, Permission action) {
256	        if (!allows(sheetId, user, action)) {
257	            throw new PermissionRefusedException(user, action);
258	        }
259	    }
