261	    /** Set the roles that may take an action on the sheet; none keeps the standing rule. */
262	    @Transactional
263	    public void setPermission(String sheetId, String by, Permission action, List<Role> allowed) {
264	        sheets.lock(sheetId);
265	        String value = String.join(",", allowed.stream().map(Role::label).toList());
266	        Optional<SheetPermission> existing = permissions.findBySheetIdAndAction(sheetId, action.label());
267	        if (value.isEmpty()) {
268	            existing.ifPresent(p -> {
269	                permissions.delete(p);
270	                permissions.flush();
271	            });
272	        } else {
273	            SheetPermission saved = existing.orElseGet(() -> new SheetPermission(sheetId, action.label(), value));
274	            saved.setRoles(value);
275	            permissions.saveAndFlush(saved);
276	        }
277	        history.settingSet(sheetId, PERMISSION + action.label(), value.isEmpty() ? null : value);
278	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=perm-" + action.label()
279	                + " value=" + value);
280	    }
