564	     *  day, the day standing in for the sheet's today (null: as it stands now). */
565	    public RoundingMode roundingOn(String sheetId, LocalDate date, LocalDate asOf) {
566	        RoundingMode mode = inForce(sheetId, "rounding", date, asOf).map(SettingValue::getText)
567	                .map(ROUNDING_MODES::get).orElse(null);
568	        if (mode != null) {
569	            return mode;
570	        }
571	        LocalDate policy = asOf == null ? policyDate(sheetId) : history.policyDate(sheetId, asOf);
