953	    /** Change the sheet's parent sheet; null leaves it blank (none). The sheet itself, a sheet that
954	     *  has this sheet as an ancestor, and a sheet never loaded are refused. */
955	    @Transactional
956	    public Sheet setParent(String sheetId, String by, String parentId) {
957	        sheets.load(sheetId);
958	        if (parentId != null) {
959	            if (parentId.equals(sheetId)) {
960	                throw new ParentRefusedException("A sheet cannot be its own parent.");
961	            }
962	            if (!sheetRepository.existsById(parentId)) {
963	                throw new ParentRefusedException("The parent sheet " + parentId + " has never been loaded.");
964	            }
965	            List<String> seen = new ArrayList<>();
966	            for (String up = parentId; up != null && !seen.contains(up);
967	                    up = sheetRepository.findById(up).map(Sheet::getParentId).orElse(null)) {
968	                if (up.equals(sheetId)) {
969	                    throw new ParentRefusedException("The sheet " + parentId + " has this sheet as an ancestor.");
970	                }
971	                seen.add(up);
972	            }
973	        }
974	        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
975	        sheet.setParentId(parentId);
976	        Sheet saved = sheetRepository.saveAndFlush(sheet);
977	        history.settingSet(sheetId, PARENT, parentId);
978	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=parent value="
979	                + (parentId != null ? parentId : ""));
980	        return saved;
981	    }
